head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > columnEllipsis]<br/>아이템 리스트창에 아이템의 라벨값이 모두 표시되지 않을때 '...' 줄임표를 표시할지 설정합니다.",
    "validation" : [            
        "아이템이 GridViewItemSet 으로 정의된 경우 각 컬럼에 '...' 줄임표가 자동으로 표시됩니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {

}



scwin.btn_getItemClass_onclick = function (e) {
    // `tr` 요소를 먼저 선택하되, "w2grid_hidedRow" 클래스가 포함되지 않는 요소만 선택합니다.
    let rows = document.querySelectorAll('tr:not(.w2grid_hidedRow)');

    // 각 행을 순회
    for (let i = 0; i < rows.length; i++) {
        // 해당 tr 내에 존재하는 id 속성값이 target1_gridViewItemTable_gridView_cell을 포함하는 요소를 찾습니다.
        let targetElements = rows[i].querySelectorAll('[id*=target1_gridViewItemTable_gridView_cell]');

        // 각 타겟 요소에 대해 처리를 수행합니다.
        for (let j = 0; j < targetElements.length; j++) {
            // 요소의 computed style 가져오기
            let computedStyle = window.getComputedStyle(targetElements[j]);

            // text-overflow 값 가져오기
            let textOverflowValue = computedStyle.getPropertyValue('text-overflow');

            // 결과 값을 설정합니다.
            wf_body_bottom.getObj("scwin").setReturnValue("cell 의 text-overflow : " + textOverflowValue);
        }
    }
};
